<?php
require_once __DIR__ . '/../bootstrap.php'; require_admin();
$isEdit = true; $id = filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); if($isEdit && !$id){set_flash('error','ID sản phẩm không hợp lệ.');header('Location: '.admin_url('products/index.php'));exit;}
$product=['name'=>'','category_id'=>'','brand'=>'','cpu'=>'','ram'=>'','description'=>'','price'=>'','stock'=>'0','image'=>''];
if($isEdit){$st=$conn->prepare('SELECT * FROM products WHERE id=?');$st->execute([$id]);$found=$st->fetch(PDO::FETCH_ASSOC);if(!$found){set_flash('error','Không tìm thấy sản phẩm.');header('Location: '.admin_url('products/index.php'));exit;}$product=$found;}
$categories=$conn->query('SELECT id,name FROM categories ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); foreach(['name','category_id','brand','cpu','ram','description','price','stock'] as $k)$product[$k]=trim($_POST[$k]??'');
 if($product['name']==='')$error='Tên sản phẩm không được để trống.';
 elseif(!is_numeric($product['price']) || (float)$product['price']<0)$error='Giá sản phẩm phải là số không âm.';
 elseif(filter_var($product['stock'],FILTER_VALIDATE_INT)===false || (int)$product['stock']<0)$error='Tồn kho phải là số nguyên không âm.';
 else{
  $category = $product['category_id']==='' ? null : filter_var($product['category_id'],FILTER_VALIDATE_INT);
  if($product['category_id']!=='' && !$category)$error='Danh mục không hợp lệ.';
  $imageName=$product['image']??'';
  if(!$error && isset($_FILES['image']) && $_FILES['image']['error']!==UPLOAD_ERR_NO_FILE){
   $f=$_FILES['image']; if($f['error']!==UPLOAD_ERR_OK)$error='Tải ảnh lên thất bại.';
   elseif($f['size']>5*1024*1024)$error='Ảnh không được lớn hơn 5 MB.';
   else{$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];if(!isset($allowed[$mime]))$error='Chỉ chấp nhận ảnh JPG, PNG, WEBP hoặc GIF.';else{$uploadDir=__DIR__.'/../../image/';if(!is_dir($uploadDir) || !is_writable($uploadDir))$error='Thư mục image/ không tồn tại hoặc không có quyền ghi.';else{$imageName='product_'.bin2hex(random_bytes(8)).'.'.$allowed[$mime];if(!move_uploaded_file($f['tmp_name'],$uploadDir.$imageName))$error='Không lưu được ảnh tải lên.';}}}
  }
  if(!$error){try{$data=[$category?:null,$product['name'],$product['brand']?:null,$product['cpu']?:null,$product['ram']?:null,$product['description']?:null,(float)$product['price'],(int)$product['stock'],$imageName?:null];if($isEdit){$data[]=$id;$st=$conn->prepare('UPDATE products SET category_id=?,name=?,brand=?,cpu=?,ram=?,description=?,price=?,stock=?,image=? WHERE id=?');$st->execute($data);set_flash('success','Đã cập nhật sản phẩm.');}else{$st=$conn->prepare('INSERT INTO products(category_id,name,brand,cpu,ram,description,price,stock,image) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute($data);set_flash('success','Đã thêm sản phẩm mới.');}header('Location: '.admin_url('products/index.php'));exit;}catch(PDOException $e){$error='Không thể lưu sản phẩm. Vui lòng kiểm tra lại dữ liệu.';}}
 }
}
admin_header($isEdit?'Sửa sản phẩm':'Thêm sản phẩm'); ?>
<?php if($error): ?><div class="alert alert-error"><?= h($error) ?></div><?php endif; ?><section class="card"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?= h(csrf_token()) ?>"><div class="form-group"><label for="name">Tên sản phẩm *</label><input class="form-control" id="name" name="name" maxlength="150" required value="<?= h($product['name']) ?>"></div><div class="detail-grid"><div class="form-group"><label for="category_id">Danh mục</label><select class="form-control" id="category_id" name="category_id"><option value="">-- Chưa phân loại --</option><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (string)$product['category_id']===(string)$c['id']?'selected':'' ?>><?= h($c['name']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label for="brand">Thương hiệu</label><input class="form-control" id="brand" name="brand" maxlength="50" value="<?= h($product['brand']) ?>"></div><div class="form-group"><label for="cpu">CPU</label><input class="form-control" id="cpu" name="cpu" maxlength="100" value="<?= h($product['cpu']) ?>"></div><div class="form-group"><label for="ram">RAM</label><input class="form-control" id="ram" name="ram" maxlength="50" value="<?= h($product['ram']) ?>"></div><div class="form-group"><label for="price">Giá (VNĐ) *</label><input class="form-control" id="price" name="price" type="number" min="0" step="1" required value="<?= h($product['price']) ?>"></div><div class="form-group"><label for="stock">Số lượng tồn kho *</label><input class="form-control" id="stock" name="stock" type="number" min="0" step="1" required value="<?= h($product['stock']) ?>"></div></div><div class="form-group"><label for="description">Mô tả</label><textarea class="form-control" id="description" name="description" rows="4"><?= h($product['description']) ?></textarea></div><div class="form-group"><label for="image">Ảnh sản phẩm</label><?php if(!empty($product['image'])): ?><div style="margin:8px 0"><img class="product-thumb" src="<?= h(site_url('image/'.rawurlencode(basename($product['image'])))) ?>" alt="Ảnh hiện tại"><span class="text-muted"> Ảnh hiện tại: <?= h($product['image']) ?></span></div><?php endif; ?><input class="form-control" id="image" name="image" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><div class="form-help">Ảnh JPG, PNG, WEBP hoặc GIF; tối đa 5 MB. Ảnh được lưu trong thư mục image/ dùng chung.</div></div><div class="form-actions"><button class="btn btn-success" type="submit"><?= $isEdit?'Lưu thay đổi':'Thêm sản phẩm' ?></button><a class="btn btn-outline" href="<?= h(admin_url('products/index.php')) ?>">Hủy</a></div></form></section><?php admin_footer(); ?>
